CREATE TABLE `batches` (
  `id` int NOT NULL AUTO_INCREMENT,
  `code` varchar(24) NOT NULL,
  `program_id` int NOT NULL,
  `batch_name` varchar(180) NOT NULL,
  `timings` varchar(120) DEFAULT NULL,
  `training_schedule` varchar(120) DEFAULT NULL,
  `mode` varchar(40) DEFAULT NULL,
  `total_seats` int DEFAULT NULL,
  `available_seats` int DEFAULT NULL,
  `start_date` varchar(40) DEFAULT NULL,
  `end_date` varchar(40) DEFAULT NULL,
  `application_deadline` varchar(40) DEFAULT NULL,
  `status` varchar(40) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ix_batches_code` (`code`),
  KEY `program_id` (`program_id`),
  CONSTRAINT `batches_ibfk_1` FOREIGN KEY (`program_id`) REFERENCES `training_programs` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2026303501 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
