DROP TABLE IF EXISTS `enrollments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `enrollments` (
  `id` int NOT NULL AUTO_INCREMENT,
  `code` varchar(28) NOT NULL,
  `citizen_ref` varchar(80) NOT NULL,
  `program_id` int NOT NULL,
  `batch_id` int DEFAULT NULL,
  `skill_name` varchar(180) NOT NULL,
  `program_title` varchar(180) NOT NULL,
  `citizen_name` varchar(180) NOT NULL,
  `citizen_email` varchar(180) NOT NULL,
  `citizen_phone` varchar(30) DEFAULT NULL,
  `selected_mode` varchar(40) DEFAULT NULL,
  `applicant_statement` text,
  `status` varchar(40) DEFAULT NULL,
  `admin_remarks` text,
  `training_progress_pct` int DEFAULT NULL,
  `attendance_pct` int DEFAULT NULL,
  `assessment_score` int DEFAULT NULL,
  `certificate_issued` tinyint(1) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `application_details` text,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ix_enrollments_code` (`code`),
  KEY `batch_id` (`batch_id`),
  KEY `program_id` (`program_id`),
  KEY `ix_enrollments_citizen_ref` (`citizen_ref`),
  KEY `ix_enrollments_status` (`status`),
  CONSTRAINT `enrollments_ibfk_1` FOREIGN KEY (`batch_id`) REFERENCES `batches` (`id`),
  CONSTRAINT `enrollments_ibfk_2` FOREIGN KEY (`program_id`) REFERENCES `training_programs` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2026304503 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
