DROP TABLE IF EXISTS `skills`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `skills` (
  `id` int NOT NULL AUTO_INCREMENT,
  `code` varchar(24) NOT NULL,
  `name` varchar(180) NOT NULL,
  `category_id` int DEFAULT NULL,
  `category_name` varchar(120) NOT NULL,
  `level` varchar(40) DEFAULT NULL,
  `duration_weeks` int DEFAULT NULL,
  `duration_hours` int DEFAULT NULL,
  `summary` text,
  `details` text,
  `prerequisites` text,
  `learning_objectives` text,
  `learning_outcomes` text,
  `relevant_industries` varchar(255) DEFAULT NULL,
  `career_opportunities` text,
  `cert_info` text,
  `rating` float DEFAULT NULL,
  `enrolled_count` int DEFAULT NULL,
  `active` tinyint(1) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ix_skills_code` (`code`),
  UNIQUE KEY `ix_skills_name` (`name`),
  KEY `category_id` (`category_id`),
  KEY `ix_skills_category_name` (`category_name`),
  KEY `ix_skills_level` (`level`),
  CONSTRAINT `skills_ibfk_1` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2026308503 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

